#!/usr/bin/env bash
# Regenerates the Python gRPC stubs consumed by services/agent.
# C++ stubs are generated by CMake from proto/CMakeLists.txt.
set -euo pipefail
cd "$(dirname "$0")/.."

PYTHON="${PYTHON:-python3}"
OUT_DIR="services/agent/avplayer_agent"

"$PYTHON" -m grpc_tools.protoc \
  -I proto \
  --python_out="$OUT_DIR" \
  --grpc_python_out="$OUT_DIR" \
  proto/agent.proto

# Generated grpc code imports the protobuf module as a top-level module;
# inside the installed package it must be a sibling import.
"$PYTHON" - "$OUT_DIR/agent_pb2_grpc.py" <<'PY'
import sys
from pathlib import Path

path = Path(sys.argv[1])
text = path.read_text(encoding="utf-8")
text = text.replace("import agent_pb2 as agent__pb2", "from . import agent_pb2 as agent__pb2")
path.write_text(text, encoding="utf-8")
PY

echo "Generated $OUT_DIR/agent_pb2.py and agent_pb2_grpc.py"
